mapper.select:
with claimTable as ( select sumt.ebank_serial_number, sum(ebcrr.claim_amount) claim_amount from eg_non_confirm_collection_sum sumt inner join eg_business_claim_repayment_record ebcrr on ebcrr.ebank_serial_number = ANY(STRING_TO_ARRAY(sumt.ebank_serial_number, ',')) and ebcrr.del_flag ='0' and ebcrr.process_status in ('3', '4') where sumt.del_flag ='0' group by sumt.ebank_serial_number ) select * from ( select cre.id, cre.system_code, case when ehfobbnm.online_bank_no is not null then ehfobbnm.online_bank_no else cre.ebank_serial_number end as business_ebank_number , cre.ebank_serial_number, cre.claim_amount , cre.process_status , cre.voucher_ids businessVoucherIds, cre.business_date , cre.client_code, cre.contract_code, cre.currency_type, cre.order_id, cre.org_id, cre.org_name, cre.new_ebank_serial_number, cre.is_cross_org, csd.id detailId, ccs.id sum_id, csd.system_name, csd.business_date systemDate, csd.business_happen_date, ccs.bank_amount, csd.remain_non_confirm_amount, csd.confirm_amount, csd.write_off_voucher_id, csd.manual_voucher_ids, csd.voucher_ids, csd.cur_claim_amount, csd.is_relate_client_auxiliary_account, coalesce(ct.claim_amount,0) claimAmountTotal from eg_business_claim_repayment_record cre inner join eg_non_confirm_collection_sum ccs on cre.ebank_serial_number = ANY(STRING_TO_ARRAY(ccs.ebank_serial_number, ',')) and ccs.del_flag ='0' inner join claimTable ct on ct.ebank_serial_number = ccs.ebank_serial_number left join eg_non_confirm_collection_second_detail csd on csd.id = cre.non_confirm_second_detail_id and csd.del_flag = '0' left join eg_hy_full_online_bank_batch_no_mapping ehfobbnm on ehfobbnm.deduct_batch_no=cre.ebank_serial_number where cre.del_flag = '0' and cre.process_status in ('3','4') ) a where 1=1
and a.business_ebank_number = #{params.businessEbankNumber}
and a.ebank_serial_number = #{params.ebankSerialNumber}
and to_char(a.business_date, 'yyyy-mm') = #{params.incomeDateString}
